//-- POWER

#define SX_PA_DAC_IO              IO_P26 // the PA gain (ELRS power_apc2)

void sx1276_rfpower_calc(const int8_t power_dbm, int8_t* sx_power, int8_t* actual_power_dbm)
{
    if (power_dbm >= POWER_33_DBM) {
        *sx_power = 0;
        *actual_power_dbm = 33;
        dacWrite(SX_PA_DAC_IO, 225);
    } else if (power_dbm >= POWER_30_DBM) {
        *sx_power = 0;
        *actual_power_dbm = 30;
        dacWrite(SX_PA_DAC_IO, 150);
    } else if (power_dbm >= POWER_27_DBM) {
        *sx_power = 0;
        *actual_power_dbm = 27;
        dacWrite(SX_PA_DAC_IO, 110);
    } else if (power_dbm >= POWER_24_DBM) {
        *sx_power = 0;
        *actual_power_dbm = 24;
        dacWrite(SX_PA_DAC_IO, 60);
    } else if (power_dbm >= POWER_20_DBM) {
        *sx_power = 0;
        *actual_power_dbm = 20;
        dacWrite(SX_PA_DAC_IO, 40);
    } else if (power_dbm >= POWER_17_DBM) {
        *sx_power = 0;
        *actual_power_dbm = 17;
        dacWrite(SX_PA_DAC_IO, 30);
    } else if (power_dbm >= POWER_14_DBM) {
        *sx_power = 0;
        *actual_power_dbm = 14;
        dacWrite(SX_PA_DAC_IO, 20);
    } else {
        *sx_power = 0;
        *actual_power_dbm = 10;
        dacWrite(SX_PA_DAC_IO, 10);
    }
}

